// -- Inference -------------------------------------------------
// Forward pass: returns best action index (0-4)
// input[5] = {front, f_right, f_left, last_left_motor, last_right_motor}

static inline void matmul_relu(
    const float* input, int in_dim,
    const float weight[][16], const float* bias, int out_dim,  // max hidden=16
    float* output)
{
    for (int o = 0; o < out_dim; o++) {
        float sum = pgm_read_float(&bias[o]);
        for (int i = 0; i < in_dim; i++) {
            sum += input[i] * pgm_read_float(&weight[o][i]);
        }
        output[o] = (sum > 0.0f) ? sum : 0.0f;  // ReLU
    }
}

int q_model_predict(const float input[Q_INPUT_DIM]) {
    float h1[Q_HIDDEN1];
    float h2[Q_HIDDEN2];
    float qvals[Q_OUTPUT_DIM];

    // Layer 1: input(5) -> h1(16) + ReLU
    for (int o = 0; o < Q_HIDDEN1; o++) {
        float sum = pgm_read_float(&W1_bias[o]);
        for (int i = 0; i < Q_INPUT_DIM; i++) {
            sum += input[i] * pgm_read_float(&W1_weight[o][i]);
        }
        h1[o] = (sum > 0.0f) ? sum : 0.0f;
    }

    // Layer 2: h1(16) -> h2(16) + ReLU
    for (int o = 0; o < Q_HIDDEN2; o++) {
        float sum = pgm_read_float(&W2_bias[o]);
        for (int i = 0; i < Q_HIDDEN1; i++) {
            sum += h1[i] * pgm_read_float(&W2_weight[o][i]);
        }
        h2[o] = (sum > 0.0f) ? sum : 0.0f;
    }

    // Layer 3: h2(16) -> qvals(5) (no activation)
    for (int o = 0; o < Q_OUTPUT_DIM; o++) {
        float sum = pgm_read_float(&W3_bias[o]);
        for (int i = 0; i < Q_HIDDEN2; i++) {
            sum += h2[i] * pgm_read_float(&W3_weight[o][i]);
        }
        qvals[o] = sum;
    }

    // Argmax
    int best = 0;
    for (int i = 1; i < Q_OUTPUT_DIM; i++) {
        if (qvals[i] > qvals[best]) best = i;
    }
    return best;
}

